example.code:
let breaker = CircuitBreaker::default();
let result = breaker.try_call(|| {
    // Protected operation
    external_service.call()
});
match result {
    Ok(response) => println!("Success: {:?}", response),
    Err(CircuitError::Open) => println!("Circuit open, failing fast"),
    Err(CircuitError::Inner(e)) => println!("Operation failed: {:?}", e),
}

use atomic_capsule::patterns::CircuitBreaker;

let breaker = CircuitBreaker::default();

// Check state before making call
if !breaker.is_open() {
    match external_service.call() {
        Ok(result) => {
            breaker.record_success();
            Ok(result)
        }
        Err(e) => {
            breaker.record_failure();
            Err(e)
        }
    }
} else {
    Err("Circuit is open, failing fast")
}

use atomic_capsule::patterns::CircuitBreaker;

let breaker = CircuitBreaker::new(CircuitBreakerConfig {
    failure_threshold: 3,
    success_threshold: 2,
    timeout_ms: 10_000,
});

// Automatic acquire + call + record
let result = breaker.try_call(|| {
    database.query("SELECT * FROM users")
});

use atomic_capsule::patterns::CircuitBreaker;

let breaker = CircuitBreaker::default();

// Periodic monitoring
loop {
    let metrics = breaker.metrics();
    println!("State: {:?}", metrics.state);
    println!("Failures: {}", metrics.failure_count);
    println!("Generation: {}", metrics.generation);

    std::thread::sleep(Duration::from_secs(1));
}
